import * as T from './vendor/three.module.js';
export const cashLabel=value=>value>=100?'$'+value/100:value+'¢';
export function cashTexture(value,reset=false){const c=document.createElement('canvas');c.width=1024;c.height=512;const x=c.getContext('2d');x.fillStyle=reset?'#7c4739':value>=100?'#d8d9ba':'#dec59a';x.fillRect(0,0,1024,512);x.strokeStyle=reset?'#dac59a':'#3b4c37';x.lineWidth=16;x.strokeRect(12,12,1000,488);x.fillStyle=reset?'#f5dfba':'#112017';x.textAlign='center';x.textBaseline='middle';x.font=reset?'bold 200px Arial':'bold 405px Arial';x.fillText(reset?'RETURN':cashLabel(value),512,reset?222:228,950);x.font='bold 50px Arial';x.fillText(reset?'BACKSPACE / 重新找零':value>=100?'DOLLARS':'CENTS',512,448,950);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.magFilter=T.LinearFilter;t.minFilter=T.LinearMipmapLinearFilter;return t;}
